create or replace function public.caleris_sync_xp_milestones() returns trigger language plpgsql security definer set search_path=public as $$declare total_xp numeric;d record;begin select coalesce(sum(amount),0) into total_xp from public.caleris_xp_ledger where member_id=new.member_id;for d in select * from public.caleris_milestone_definitions where scope='driver' and metric_key='xp_total' and active loop insert into public.caleris_milestone_progress(milestone_id,scope,member_id,current_value,completed_at) values(d.id,'driver',new.member_id,total_xp,case when total_xp>=d.target_value then now() end) on conflict(milestone_id,member_id) do update set current_value=excluded.current_value,completed_at=coalesce(caleris_milestone_progress.completed_at,excluded.completed_at),updated_at=now();if total_xp>=d.target_value then if d.badge_code is not null then insert into public.caleris_member_badges(member_id,badge_code,source_type,source_id) values(new.member_id,d.badge_code,'milestone',d.code) on conflict do nothing;end if;if d.xp_reward>0 then insert into public.caleris_xp_ledger(member_id,amount,source_type,source_id,description) values(new.member_id,d.xp_reward,'milestone',d.code,'Milestone reward: '||d.title) on conflict(member_id,source_type,source_id) do nothing;end if;end if;end loop;return new;end$$;
drop trigger if exists caleris_xp_milestone_sync on public.caleris_xp_ledger;
create trigger caleris_xp_milestone_sync after insert on public.caleris_xp_ledger for each row execute function public.caleris_sync_xp_milestones();